/**
Write "Congratulations, <username>!" to a buffer. The buffer will be printed by the caller.

@param buffer: the buffer to write to
@param buffer_size: the size of the buffer
@param userName: the username to congratulate
@param userName_size: the size of the username
*/
void congratulate_user(char* buffer, int buffer_size, const char *userName, int userName_size)
{
    const char* prefix = "Congratulations, ";
    int prefix_len = strlen(prefix);
    const char* suffix = "!";
    int suffix_len = strlen(suffix);

    // Calculate the total length of the desired string including prefix, username, suffix, and null terminator.
    int required_len = prefix_len + userName_size + suffix_len + 1;

    // If the buffer is too small to hold the entire string, truncate.
    if (buffer_size < required_len) {
        // Copy the prefix, ensuring it doesn't overflow.
        strncpy(buffer, prefix, buffer_size - 1);
        buffer[buffer_size - 1] = '\0'; // Ensure null termination

        // Calculate how much space is left for the username and suffix.
        int current_len = strlen(buffer);
        int remaining_space = buffer_size - current_len - 1; // -1 for the null terminator

        // If there's space, append as much of the username as possible.
        if (remaining_space > 0) {
            int userName_to_copy = (userName_size < remaining_space) ? userName_size : remaining_space;
            strncat(buffer, userName, userName_to_copy);
            current_len = strlen(buffer);
            remaining_space = buffer_size - current_len - 1;

            // If there's still space, append the suffix.
            if (remaining_space > 0) {
                strncat(buffer, suffix, remaining_space);
            }
        }
    } else {
        // If the buffer is large enough, construct the full string.
        strcpy(buffer, prefix);
        strcat(buffer, userName);
        strcat(buffer, suffix);
        // The null terminator is automatically handled by strcat if there's sufficient space.
        // To be absolutely safe, ensure it if buffer_size is exactly required_len.
        if (buffer_size == required_len) {
            buffer[buffer_size - 1] = '\0';
        }
    }
}
